#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


set -E

DEFAULT_PROJECT="project-47b72bb7-ba90-42c9-910"
DEFAULT_ZONE="us-west1-b"
DEFAULT_INSTANCE="epm-h02-host"

LOCAL_BUILD_DIR="/private/tmp/epm-build"
LOCAL_CONTEXTS_ARCHIVE="/private/tmp/epm-contexts.tar.gz"

HOST_SERVICES=(
  epm-h03-identity.service
  epm-gateway.service
  epm-tunnel.service
  epm-backup-proxy.service
  epm-host-guardian.service
  google-cloud-ops-agent.service
)

die() { printf '\nStopped: %s\n' "$*" >&2; exit 1; }
need() { command -v "$1" >/dev/null 2>&1 || die "Required command missing: $1"; }
valid_gcp_ident() { [[ "$1" =~ ^[a-z0-9][a-z0-9-]*$ ]]; }
valid_container_name() { [[ "$1" =~ ^[A-Za-z0-9][A-Za-z0-9_.-]*$ ]]; }
valid_opt_dir_name() { [[ "$1" =~ ^[A-Za-z0-9][A-Za-z0-9._-]*$ ]]; }
valid_image_ref() {
  [[ -n "$1" && "$1" != *$'\n'* && "$1" != *$'\r'* && "$1" != *[[:space:]]* ]] \
    && [[ "$1" =~ ^(sha256:)?[0-9a-f]{12,64}$ || "$1" =~ ^[a-zA-Z0-9._/@:-]+$ ]]
}

state_directory() {
  if [[ "$(uname -s)" == Darwin ]]; then
    printf '%s/Library/Application Support/EPM/pilot0-cleanup' "$HOME"
  else
    printf '%s/epm/pilot0-cleanup' "${XDG_STATE_HOME:-$HOME/.local/state}"
  fi
}

vm_ssh() {
  local remote_cmd="$1"
  gcloud compute ssh "$EPM_INSTANCE" \
    --project="$EPM_PROJECT" \
    --zone="$EPM_ZONE" \
    --tunnel-through-iap \
    --command="$remote_cmd"
}

run_cleanup_helper() {
  local action="$1"
  shift
  local quoted_args="" arg
  for arg in "$@"; do
    quoted_args+=" $(printf '%q' "$arg")"
  done
  gcloud compute ssh "$EPM_INSTANCE" \
    --project="$EPM_PROJECT" \
    --zone="$EPM_ZONE" \
    --tunnel-through-iap \
    --command="sudo /opt/epm/python/bin/python3 -I - $(printf '%q' "$action")${quoted_args}" \
    -- -T < "$helper"
}

PARSED_ITEMS=()
parse_space_list() {
  local raw="$1"
  PARSED_ITEMS=()
  [[ -z "$raw" ]] && return 0
  IFS=$' \t' read -r -a PARSED_ITEMS <<< "$raw"
}

prompt_connection() {
  need gcloud
  say "Target Pilot 0 host (Press Enter to keep defaults):"
  ask EPM_PROJECT "GCP Project ID [blank: $DEFAULT_PROJECT]:"
  EPM_PROJECT="${EPM_PROJECT:-$DEFAULT_PROJECT}"
  valid_gcp_ident "$EPM_PROJECT" || die "Invalid GCP Project ID: $EPM_PROJECT"

  ask EPM_ZONE "GCP Zone [blank: $DEFAULT_ZONE]:"
  EPM_ZONE="${EPM_ZONE:-$DEFAULT_ZONE}"
  valid_gcp_ident "$EPM_ZONE" || die "Invalid GCP Zone: $EPM_ZONE"

  ask EPM_INSTANCE "GCP Host Instance [blank: $DEFAULT_INSTANCE]:"
  EPM_INSTANCE="${EPM_INSTANCE:-$DEFAULT_INSTANCE}"
  valid_gcp_ident "$EPM_INSTANCE" || die "Invalid GCP Instance: $EPM_INSTANCE"

  write_env EPM_PROJECT "$EPM_PROJECT"
  write_env EPM_ZONE "$EPM_ZONE"
  write_env EPM_INSTANCE "$EPM_INSTANCE"
}

show_disk_usage() {
  vm_ssh 'df -h / /srv/epm/data && echo "" && sudo docker system df'
}

collect_keep_args() {
  KEEP_ARGS=()
  say "Automatic protections (always enforced on the host):"
  step "All running containers and their images"
  step "Active Admin MANIFEST image (/opt/epm/h0312/run_identity.py)"
  step "Latest qualified_releases catalog entry & operator-referenced releases in admin.sqlite"
  step "Offline-build Python base image (python:*)"
  step "Core /opt/epm runtime directories and anything referenced by systemd, /etc/epm, or running processes"
  step "All workspace, control, and backup data under /srv/epm/data (never touched)"
  printf '\n'
  note "Optional: enter space-separated rollback image tags or short IDs to protect in addition to live images."
  note "Example: epm-pilot0-operator:pilot0-20261125-tasks epm-pilot0-admin:pilot0-20261125-tasks"
  local raw_keeps="" item
  printf '  %sAdditional rollback images to KEEP [blank: none]:%s ' "$BOLD" "$RESET"
  read -r raw_keeps || true
  parse_space_list "$raw_keeps"
  for item in "${PARSED_ITEMS[@]+"${PARSED_ITEMS[@]}"}"; do
    valid_image_ref "$item" || die "Invalid image reference in keep list: $item"
    KEEP_ARGS+=(--keep "$item")
  done
}

action_inspect() {
  stage "Connect & check disk usage"
  prompt_connection
  show_disk_usage

  stage "Read-only release & disk cleanup inventory"
  collect_keep_args
  run_cleanup_helper inspect "${KEEP_ARGS[@]+"${KEEP_ARGS[@]}"}"
  say "Read-only inspection complete. No files, containers, or images were modified."
}

action_cleanup() {
  stage "Connect & snapshot current disk usage"
  prompt_connection
  say "Current disk usage on $EPM_INSTANCE:"
  show_disk_usage
  pause "Press Enter to inspect protected vs. removable release artifacts..."

  stage "Choose rollback images to retain & review inventory"
  collect_keep_args
  run_cleanup_helper inspect "${KEEP_ARGS[@]+"${KEEP_ARGS[@]}"}"
  pause "Review the KEEP vs. REMOVABLE inventory above, then press Enter to continue..."

  stage "Remove stopped/exited containers"
  note "Removing old stopped containers unpins old Docker images so Stage 4 can reclaim them."
  say "Choose how to handle stopped containers:"
  step "all    — remove all stopped/exited containers (never touches running containers)"
  step "select — enter specific container names to remove"
  step "skip   — leave stopped containers untouched"
  local ctr_choice=""
  printf '  %sStopped container action [all/select/skip, default: skip]:%s ' "$BOLD" "$RESET"
  read -r ctr_choice || true
  ctr_choice="${ctr_choice:-skip}"
  case "$ctr_choice" in
    all)
      if confirm "Remove ALL stopped/exited containers on $EPM_INSTANCE?"; then
        run_cleanup_helper remove-containers --all-stopped
      else
        SKIPPED+=("Stopped container cleanup")
      fi
      ;;
    select)
      local raw_ctrs="" c_name c_args=()
      printf '  %sSpace-separated stopped container names to remove:%s ' "$BOLD" "$RESET"
      read -r raw_ctrs || true
      parse_space_list "$raw_ctrs"
      for c_name in "${PARSED_ITEMS[@]+"${PARSED_ITEMS[@]}"}"; do
        valid_container_name "$c_name" || die "Invalid container name: $c_name"
        c_args+=(--container "$c_name")
      done
      if (( ${#c_args[@]} )); then
        run_cleanup_helper remove-containers "${c_args[@]}"
      else
        warn "No container names provided; skipped."
      fi
      ;;
    skip)
      SKIPPED+=("Stopped container cleanup")
      say "Skipped stopped container cleanup."
      ;;
    *)
      die "Unknown option: $ctr_choice (expected all, select, or skip)."
      ;;
  esac

  stage "Remove unused Docker images"
  say "Re-evaluating image protections after container cleanup..."
  run_cleanup_helper inspect "${KEEP_ARGS[@]+"${KEEP_ARGS[@]}"}"
  printf '\n'
  say "Choose how to handle REMOVABLE Docker images:"
  step "all    — remove all REMOVABLE images (never removes KEEP/protected images)"
  step "select — enter specific image tags or short IDs to remove"
  step "skip   — leave Docker images untouched"
  local img_choice=""
  printf '  %sUnused image action [all/select/skip, default: skip]:%s ' "$BOLD" "$RESET"
  read -r img_choice || true
  img_choice="${img_choice:-skip}"
  case "$img_choice" in
    all)
      local confirm_word=""
      printf '  %sType DELETE to permanently remove all REMOVABLE Docker images:%s ' "$YELLOW" "$RESET"
      read -r confirm_word || true
      if [[ "$confirm_word" == "DELETE" ]]; then
        run_cleanup_helper remove-images --all-removable "${KEEP_ARGS[@]+"${KEEP_ARGS[@]}"}"
      else
        SKIPPED+=("Unused Docker image removal")
        warn "Confirmation did not match DELETE; skipped image removal."
      fi
      ;;
    select)
      local raw_imgs="" i_ref i_args=()
      printf '  %sSpace-separated image tags or short IDs to remove:%s ' "$BOLD" "$RESET"
      read -r raw_imgs || true
      parse_space_list "$raw_imgs"
      for i_ref in "${PARSED_ITEMS[@]+"${PARSED_ITEMS[@]}"}"; do
        valid_image_ref "$i_ref" || die "Invalid image reference: $i_ref"
        i_args+=(--image "$i_ref")
      done
      if (( ${#i_args[@]} )); then
        run_cleanup_helper remove-images "${i_args[@]}" "${KEEP_ARGS[@]+"${KEEP_ARGS[@]}"}"
      else
        warn "No images specified; skipped."
      fi
      ;;
    skip)
      SKIPPED+=("Unused Docker image removal")
      say "Skipped unused Docker image removal."
      ;;
    *)
      die "Unknown option: $img_choice (expected all, select, or skip)."
      ;;
  esac

  stage "Prune Docker build cache, /tmp staging & unreferenced /opt/epm dirs"
  say "1. Docker Build Cache:"
  note "  dangling — removes only unused/dangling build cache (fast next build)"
  note "  all      — reclaims the full unused build cache (next build takes ~1-2 min longer)"
  note "  skip     — keep build cache as-is"
  local cache_choice=""
  printf '  %sBuild cache prune [dangling/all/skip, default: skip]:%s ' "$BOLD" "$RESET"
  read -r cache_choice || true
  cache_choice="${cache_choice:-skip}"
  case "$cache_choice" in
    dangling)
      run_cleanup_helper prune-builder
      ;;
    all)
      if confirm "Prune ALL unused Docker build cache on $EPM_INSTANCE?"; then
        run_cleanup_helper prune-builder --all
      else
        SKIPPED+=("Docker build cache prune")
      fi
      ;;
    skip)
      SKIPPED+=("Docker build cache prune")
      ;;
    *)
      die "Unknown option: $cache_choice (expected dangling, all, or skip)."
      ;;
  esac

  printf '\n'
  say "2. Temporary build staging (/tmp/epm-contexts.tar.gz, /tmp/build, /tmp/epm-*):"
  if confirm "Remove temporary EPM build staging files in /tmp on $EPM_INSTANCE?"; then
    run_cleanup_helper remove-tmp
  else
    SKIPPED+=("Remote /tmp staging cleanup")
  fi

  if [[ "$(uname -s)" == Darwin ]] && [[ -e "$LOCAL_BUILD_DIR" || -e "$LOCAL_CONTEXTS_ARCHIVE" ]]; then
    if confirm "Also remove local macOS staging ($LOCAL_BUILD_DIR, $LOCAL_CONTEXTS_ARCHIVE; keeps /private/tmp/epm-agent-bundle)?"; then
      rm -rf "$LOCAL_BUILD_DIR" "$LOCAL_CONTEXTS_ARCHIVE"
      say "Removed local macOS build staging."
    fi
  fi

  printf '\n'
  say "3. Unreferenced /opt/epm qualification & legacy agent directories:"
  note "Core runtime dirs (python, agent-bundle, demo, h0312, pilot0, host-agent, tools)"
  note "and anything referenced by systemd, /etc/epm, symlinks, or running processes are protected."
  local opt_choice=""
  printf '  %sUnreferenced /opt/epm action [all/select/skip, default: skip]:%s ' "$BOLD" "$RESET"
  read -r opt_choice || true
  opt_choice="${opt_choice:-skip}"
  case "$opt_choice" in
    all)
      local opt_confirm=""
      printf '  %sType DELETE to remove all unreferenced /opt/epm directories:%s ' "$YELLOW" "$RESET"
      read -r opt_confirm || true
      if [[ "$opt_confirm" == "DELETE" ]]; then
        run_cleanup_helper remove-opt-dirs --all-unreferenced
      else
        SKIPPED+=("Unreferenced /opt/epm cleanup")
        warn "Confirmation did not match DELETE; skipped /opt/epm cleanup."
      fi
      ;;
    select)
      local raw_dirs="" d_name d_args=()
      printf '  %sSpace-separated /opt/epm directory names to remove:%s ' "$BOLD" "$RESET"
      read -r raw_dirs || true
      parse_space_list "$raw_dirs"
      for d_name in "${PARSED_ITEMS[@]+"${PARSED_ITEMS[@]}"}"; do
        valid_opt_dir_name "$d_name" || die "Invalid /opt/epm directory name: $d_name"
        d_args+=(--dir "$d_name")
      done
      if (( ${#d_args[@]} )); then
        run_cleanup_helper remove-opt-dirs "${d_args[@]}"
      else
        warn "No directory names provided; skipped."
      fi
      ;;
    skip)
      SKIPPED+=("Unreferenced /opt/epm cleanup")
      say "Skipped /opt/epm cleanup."
      ;;
    *)
      die "Unknown option: $opt_choice (expected all, select, or skip)."
      ;;
  esac

  stage "Verify reclaimed disk space & live host health"
  say "Updated disk usage on $EPM_INSTANCE:"
  show_disk_usage
  printf '\n'
  say "Verifying host systemd services and running containers:"
  vm_ssh "sudo systemctl is-active ${HOST_SERVICES[*]} && echo '' && sudo docker ps --format '{{.Names}}\t{{.Image}}\t{{.Status}}'"
  say "Workspace data, access databases, backups, and active releases were preserved."
}

main() {
  if [[ "${1:-}" == --help || "${1:-}" == -h ]]; then
    cat <<'EOF'
Usage: bash application/scripts/epm-pilot0-release-cleanup.sh [cleanup|inspect]

Interactive Pilot 0 hosting release cleanup wizard to reclaim disk space on epm-h02-host:
  cleanup   Inspect and interactively remove stopped containers, unused Docker images,
            Docker build cache, /tmp staging, and unreferenced /opt/epm directories
  inspect   Read-only disk usage and KEEP vs. REMOVABLE release inventory

Always protects running containers, active Admin MANIFEST image, latest/referenced
qualified_releases catalog entries, offline-build Python base images, core /opt/epm
runtime paths, and all /srv/epm/data workspace/control/backup data.
EOF
    return
  fi

  [[ $# -le 1 ]] || die "Too many arguments. Use --help for usage."
  [[ -t 0 && -t 1 ]] || die "Run interactively in a terminal."

  local script_dir helper state_dir action="${1:-}"
  script_dir="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
  helper="$script_dir/pilot0_release_cleanup.py"
  [[ -f "$helper" && ! -L "$helper" ]] || die "Place pilot0_release_cleanup.py beside this wizard."

  umask 077
  state_dir="$(state_directory)"
  mkdir -p "$state_dir"
  ENV_FILE="$state_dir/cleanup.env"
  touch "$ENV_FILE"
  chmod 600 "$ENV_FILE"

  if [[ -z "$action" ]]; then
    say "Choose action: cleanup or inspect."
    ask EPM_CLEANUP_ACTION "Action [blank: cleanup]:"
    action="${EPM_CLEANUP_ACTION:-cleanup}"
  fi

  case "$action" in
    cleanup) TOTAL_STAGES=6 ;;
    inspect) TOTAL_STAGES=2 ;;
    *) die "Unknown action: $action (choose cleanup or inspect)." ;;
  esac

  trap 'die "Cleanup interrupted or failed. Inspect live host state; no running services or workspace data were modified."' ERR INT TERM

  banner "EPM · Pilot 0 release cleanup wizard ($action)"
  case "$action" in
    cleanup) action_cleanup ;;
    inspect) action_inspect ;;
  esac
  finish
}

main "$@"
